import { IntelligenceFeatureStore } from '../core/feature-store.js';import { buildPulse } from '../pulse/pulse-fusion.js';import { buildDiscoveryFeatures } from '../tourism/discovery-feature-builder.js';import { rankDiscoveries } from '../tourism/discovery-ranker.js';import { buildWhyNow } from '../tourism/why-now.js';import { bestTravelWindows } from '../tourism/best-window.js';import { compilePollutionLens } from '../environment/pollution-lens-service.js';import { findHistoricalAnalogs } from '../memory/analog-search.js';import { rankForMe } from '../personal/relevance.js';
export class AdvancedIntelligenceService {constructor(){this.features=new IntelligenceFeatureStore();}
 travel({placeIds=[],featureRows=[],windowsByPlace={}}={}){for(const r of featureRows)this.features.append(r);const candidates=placeIds.map(placeId=>{const built=buildDiscoveryFeatures(this.features.snapshot(),{subjectId:placeId});return{placeId,features:built.features,sources:built.sources};});const ranked=rankDiscoveries(candidates);return ranked.map(x=>({...x,whyNow:buildWhyNow(x.candidate),bestWindows:bestTravelWindows(windowsByPlace[x.candidate.placeId]||[])}));}
 pulse(input){return buildPulse(input);} pollution(input){return compilePollutionLens(input);} analogs(target,history,opts){return findHistoricalAnalogs(target,history,opts);} forMe(items,context){return rankForMe(items,context);}}
